INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Grundfunktionen Computer
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Eingabe und Ausgabe grundlegende Funktionen eines Computers?', 2, '[{"text": "Ja", "correct": true, "because": "Eingabe und Ausgabe sind Kernprozesse"}, {"text": "Nein", "correct": false, "because": "Grundfunktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Computer ohne Speicherfunktion arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Speicher ist für Datenverarbeitung essenziell"}, {"text": "Ja", "correct": false, "because": "Speicher ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Verarbeitung von Daten unabhängig von der CPU?', 2, '[{"text": "Nein", "correct": true, "because": "CPU ist für Verarbeitung verantwortlich"}, {"text": "Ja", "correct": false, "because": "CPU ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Computer ohne Betriebssystem grundlegende Funktionen ausführen?', 2, '[{"text": "Nein", "correct": true, "because": "Betriebssystem koordiniert Funktionen"}, {"text": "Ja", "correct": false, "because": "OS ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kommunikation mit Peripheriegeräten eine Grundfunktion eines Computers?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Ein- und Ausgabe"}, {"text": "Nein", "correct": false, "because": "Teil der Grundfunktionen"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktion beschreibt die Datenverarbeitung in einem Computer?', 3, '[{"text": "Verarbeitung", "correct": true, "because": "Daten werden durch CPU bearbeitet"}, {"text": "Eingabe", "correct": false, "because": "Vor Verarbeitung"}, {"text": "Ausgabe", "correct": false, "because": "Nach Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist für die Speicherung von Daten zuständig?', 2, '[{"text": "RAM", "correct": true, "because": "Temporäre Datenspeicherung"}, {"text": "Monitor", "correct": false, "because": "Ausgabe"}, {"text": "Tastatur", "correct": false, "because": "Eingabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion ermöglicht die Interaktion mit dem Benutzer?', 2, '[{"text": "Eingabe", "correct": true, "because": "Erlaubt Benutzerbefehle"}, {"text": "Verarbeitung", "correct": false, "because": "Intern"}, {"text": "Speicherung", "correct": false, "because": "Datenhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element koordiniert die Grundfunktionen eines Computers?', 3, '[{"text": "Betriebssystem", "correct": true, "because": "Steuert Prozesse"}, {"text": "Festplatte", "correct": false, "because": "Speicher"}, {"text": "Grafikkarte", "correct": false, "because": "Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der Grundfunktion "Ausgabe"?', 2, '[{"text": "Sichtbare Ergebnisse", "correct": true, "because": "Macht Verarbeitung nutzbar"}, {"text": "Schnelle Eingabe", "correct": false, "because": "Andere Funktion"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Unabhängig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Grundfunktionen hat ein Computer?', 4, '[{"text": "Eingabe", "correct": true, "because": "Datenaufnahme"}, {"text": "Verarbeitung", "correct": true, "because": "Datenbearbeitung"}, {"text": "Ausgabe", "correct": true, "because": "Ergebnisdarstellung"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für die Grundfunktionen essenziell?', 3, '[{"text": "CPU", "correct": true, "because": "Verarbeitung"}, {"text": "RAM", "correct": true, "because": "Speicherung"}, {"text": "Festplatte", "correct": true, "because": "Dauerhafte Speicherung"}, {"text": "Monitorfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten die Grundfunktionen eines Computers?', 3, '[{"text": "Datenbearbeitung", "correct": true, "because": "Ermöglicht Verarbeitung"}, {"text": "Nutzerinteraktion", "correct": true, "because": "Eingabe und Ausgabe"}, {"text": "Flexibilität", "correct": true, "because": "Vielseitige Nutzung"}, {"text": "Geringer Preis", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte unterstützen die Eingabefunktion?', 4, '[{"text": "Tastatur", "correct": true, "because": "Texteingabe"}, {"text": "Maus", "correct": true, "because": "Steuerung"}, {"text": "Mikrofon", "correct": true, "because": "Spracheingabe"}, {"text": "Monitor", "correct": false, "because": "Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Grundfunktionen beeinträchtigen?', 3, '[{"text": "Hardwarefehler", "correct": true, "because": "Stört Verarbeitung"}, {"text": "Softwarefehler", "correct": true, "because": "Beeinträchtigt Koordination"}, {"text": "Stromausfall", "correct": true, "because": "Stoppt Funktionen"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eingabe ist eine Grundfunktion eines Computers. b) Speicherung ist für die Funktion optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eingabe ja, Speicher nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die CPU ist für die Verarbeitung zuständig. b) Ein Betriebssystem ist für Grundfunktionen unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CPU ja, OS nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ausgabe macht Ergebnisse sichtbar. b) Peripheriegeräte sind für Grundfunktionen irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausgabe ja, Peripherie wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) RAM speichert Daten temporär. b) Verarbeitung kann ohne CPU erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RAM ja, CPU nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Tastatur und Maus unterstützen die Eingabefunktion. b) Ein Computer kann ohne Ausgabe arbeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eingabe ja, Ausgabe nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

